contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seed) public payable {
        require(seed >= 0);

        c.NETM(); if (__ESBMC_reverted()) return;

        uint256 td = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 tr = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 ts = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balCaller = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(balCaller == td && td + tr == ts);
    }

    receive() external payable {}
}

